class Solution {
    public int racecar(int target) {
        int[] dp = new int[target + 1];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        for (int t = 1; t <= target; t++) {
            int k = 0;
            while ((1 << k) - 1 < t) k++;
            int pos = (1 << k) - 1;
            if (pos == t) { dp[t] = k; continue; }
            dp[t] = k + 1 + dp[pos - t];
            for (int j = 0; j < k - 1; j++) {
                int pos2 = (1 << (k - 1)) - 1 - ((1 << j) - 1);
                dp[t] = Math.min(dp[t], (k - 1) + 1 + j + 1 + dp[t - pos2]);
            }
        }
        return dp[target];
    }
}

import java.util.*;

class Solution {
    public int racecar(int target) {
        Set<String> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 1});
        visited.add("0,1");
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int pos = cur[0], speed = cur[1];
                if (pos == target) return steps;
                int newPos = pos + speed;
                int newSpeed = speed * 2;
                String key1 = newPos + "," + newSpeed;
                if (newPos > 0 && newPos < 2 * target && !visited.contains(key1)) {
                    visited.add(key1);
                    queue.offer(new int[]{newPos, newSpeed});
                }
                int revSpeed = speed > 0 ? -1 : 1;
                String key2 = pos + "," + revSpeed;
                if (!visited.contains(key2)) {
                    visited.add(key2);
                    queue.offer(new int[]{pos, revSpeed});
                }
            }
            steps++;
        }
        return -1;
    }
}
